Section FXALL.
Context {fx : FPState}.

Definition STOPS2 : list Z := (0xd3e38 :: STOPS)%Z.

Definition rB2 := Eval vm_compute in sym_exec RSEGS FUEL true STOPS2 scr0 (SS 0xe3ba8 srB0 [] knA 38) [].
Definition srB2 : list expr := Eval vm_compute in s_regs (fst (fst rB2)).

